        foreach (var stock in Stocks())
        foreach (var jammed in Jams)
        foreach (var amount in Amounts)
        {
            CheckWithdraw(account, stock, jammed, amount);
        }
    }

    [Fact]
    public void Withdraw_matches_oracle_for_every_account_and_amount()
